  FAR FILE *fp;
  int ret;

  ret = qiban_make_temp_path(path, temp_path, sizeof(temp_path));
  if (ret < 0)
    {
      return ret;
    }

  fp = fopen(temp_path, "w");
  if (fp == NULL)
    {
      return -errno;
    }

  if (fputs(content, fp) == EOF || ferror(fp) != 0)
    {
      fclose(fp);
      unlink(temp_path);
      return -EIO;
    }

  if (fclose(fp) != 0)
    {
      unlink(temp_path);
      return -EIO;
    }

  if (rename(temp_path, path) != 0)
    {
      unlink(temp_path);
      return -errno;
    }

  return OK;
}

