      case QIBAN_VOICE_ACTION_NAVIGATE:
        return "navigate";
      case QIBAN_VOICE_ACTION_CLEAR_NAV:
        return "clear_navigation";
      case QIBAN_VOICE_ACTION_ZOOM_IN:
        return "zoom_in";
      case QIBAN_VOICE_ACTION_ZOOM_OUT:
        return "zoom_out";
      case QIBAN_VOICE_ACTION_REFRESH_MAP:
        return "refresh_map";
      default:
        return "unknown";
    }
}

