static int qiban_json_escape(FAR const char *input, FAR char *buffer,
                             size_t buffer_size)
{
  size_t used = 0;

  while (*input != '\0')
    {
      FAR const char *replacement = NULL;
      char single[2];
      size_t needed;

      switch (*input)
        {
          case '\\':
            replacement = "\\\\";
            break;
          case '"':
            replacement = "\\\"";
            break;
          case '\n':
            replacement = "\\n";
            break;
          case '\r':
            replacement = "\\r";
            break;
          case '\t':
            replacement = "\\t";
            break;
          default:
            single[0] = *input;
            single[1] = '\0';
            replacement = single;
            break;
        }

      needed = strlen(replacement);
      if (used + needed + 1 > buffer_size)
        {
          return -ENOSPC;
        }

      memcpy(buffer + used, replacement, needed);
      used += needed;
      input++;
    }

  buffer[used] = '\0';
  return OK;
}

