static FAR const char *qiban_json_find_key(FAR const char *json,
                                           FAR const char *key)
{
  char pattern[64];

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);
  return strstr(json, pattern);
}

static bool qiban_json_extract_string(FAR const char *json,
                                      FAR const char *key,
                                      FAR char *buffer,
                                      size_t buffer_size)
{
  FAR const char *cursor;
  FAR const char *start;
  FAR const char *end;
  size_t length;

  cursor = qiban_json_find_key(json, key);
  if (cursor == NULL)
    {
      return false;
    }

  cursor = strchr(cursor, ':');
  if (cursor == NULL)
    {
      return false;
    }

  start = strchr(cursor, '"');
  if (start == NULL)
    {
      return false;
    }

  start++;
  end = strchr(start, '"');
  if (end == NULL)
    {
      return false;
    }

  length = (size_t)(end - start);
  if (length >= buffer_size)
    {
      length = buffer_size - 1;
    }

  memcpy(buffer, start, length);
  buffer[length] = '\0';
  return true;
}

static bool qiban_json_extract_int(FAR const char *json,
                                   FAR const char *key,
                                   FAR int *value)
{
  FAR const char *cursor;
  FAR char *endptr;
  long parsed;

  cursor = qiban_json_find_key(json, key);
  if (cursor == NULL)
    {
      return false;
    }

  cursor = strchr(cursor, ':');
  if (cursor == NULL)
    {
      return false;
    }

  cursor++;
  while (*cursor == ' ' || *cursor == '\t')
    {
      cursor++;
    }

  errno = 0;
  parsed = strtol(cursor, &endptr, 10);
  if (cursor == endptr || errno != 0)
    {
      return false;
    }

  *value = (int)parsed;
  return true;
}

static bool qiban_json_extract_bool(FAR const char *json,
                                    FAR const char *key,
                                    FAR bool *value)
{
  FAR const char *cursor;

  cursor = qiban_json_find_key(json, key);
  if (cursor == NULL)
    {
      return false;
    }

  cursor = strchr(cursor, ':');
  if (cursor == NULL)
    {
      return false;
    }

  cursor++;
  while (*cursor == ' ' || *cursor == '\t')
    {
      cursor++;
    }

  if (strncmp(cursor, "true", 4) == 0)
    {
      *value = true;
      return true;
    }

  if (strncmp(cursor, "false", 5) == 0)
    {
      *value = false;
      return true;
    }

  return false;
}

static int qiban_load_text_file(FAR const char *path,
                                FAR char *buffer,
                                size_t buffer_size)
{
  FAR FILE *fp;
  size_t nread;

  fp = fopen(path, "r");
  if (fp == NULL)
    {
      return -errno;
    }

  nread = fread(buffer, 1, buffer_size - 1, fp);
  fclose(fp);
  if (nread == 0)
    {
      return -EIO;
    }

  buffer[nread] = '\0';
  return OK;
}

static int qiban_spawn_and_wait(FAR char * const argv[])
{
  pid_t pid;
  int ret;
  int status;

  ret = posix_spawnp(&pid, argv[0], NULL, NULL, argv, NULL);
  if (ret != 0)
    {
      fprintf(stderr, "failed to spawn %s: %d\n", argv[0], ret);
      return -ret;
    }

  if (waitpid(pid, &status, 0) < 0)
    {
      return -errno;
    }

  if (!WIFEXITED(status))
    {
      return -ECHILD;
    }

  if (WEXITSTATUS(status) != 0)
    {
      return -WEXITSTATUS(status);
    }

  return OK;
}

