  ret = qiban_copy_file_atomic(source_path, QIBAN_VOICE_TTS_PLACEHOLDER_PCM);
  if (ret < 0)
    {
      return ret;
    }

  ret = qiban_load_text_file(QIBAN_VOICE_TTS_TEXT_PATH,
                             current_text, sizeof(current_text));
  if (ret < 0)
    {
