static int qiban_print_file(FAR const char *title, FAR const char *path)
{
  char buffer[QIBAN_VOICE_JSON_SIZE];
  FAR FILE *fp;
  size_t nread;

  printf("[%s]\n", title);

  fp = fopen(path, "r");
  if (fp == NULL)
    {
      printf("missing: %s\n", path);
      return -errno;
    }

  nread = fread(buffer, 1, sizeof(buffer) - 1, fp);
  fclose(fp);
  if (nread == 0)
    {
      printf("empty: %s\n", path);
      return -EIO;
    }

  buffer[nread] = '\0';
  printf("%s", buffer);
  return OK;
}

