+  if (!qiban_json_extract_string(json, "job_id", job_id, job_id_size) ||
+      !qiban_json_extract_string(json, "server_url", server_url,
+                                 server_url_size))
+    {
+      return -EINVAL;
+    }
+
+  return OK;
+}
