+static int qiban_http_download_file(FAR const char *url,
+                                    FAR const char *output_path)
+{
+  char temp_path[PATH_MAX];
+  CURL *curl;
+  CURLcode code;
+  long http_code = 0;
+  FILE *fp;
+  int ret;
+
+  ret = qiban_make_temp_path(output_path, temp_path, sizeof(temp_path));
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  fp = fopen(temp_path, "wb");
+  if (fp == NULL)
+    {
+      return -errno;
+    }
+
+  code = curl_global_init(CURL_GLOBAL_DEFAULT);
+  if (code != CURLE_OK)
+    {
+      fclose(fp);
+      unlink(temp_path);
+      return -EIO;
+    }
+
+  curl = curl_easy_init();
+  if (curl == NULL)
+    {
+      curl_global_cleanup();
+      fclose(fp);
+      unlink(temp_path);
+      return -ENOMEM;
+    }
+
+  curl_easy_setopt(curl, CURLOPT_URL, url);
+  curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
+  curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
+  curl_easy_setopt(curl, CURLOPT_USERAGENT, "qiban_voice_service/1.0");
+  curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);
+  curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
+  curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
+  code = curl_easy_perform(curl);
+  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
+  curl_easy_cleanup(curl);
+  curl_global_cleanup();
+
+  fclose(fp);
+  if (code != CURLE_OK || http_code < 200 || http_code >= 300)
+    {
+      unlink(temp_path);
+      return -EIO;
+    }
+
+  if (rename(temp_path, output_path) != 0)
+    {
+      unlink(temp_path);
+      return -errno;
+    }
+
+  return OK;
+}
