           "recordraw %s %d %d %d 0\n",
           QIBAN_VOICE_DEFAULT_AUDIO_DEVICE,
           pcm_path,
           QIBAN_VOICE_CHANNELS,
           QIBAN_VOICE_BITS_PER_SAMPLE,
           QIBAN_VOICE_SAMPLE_RATE_HZ);

